    (function() {
        // ==========================================
        // 【关键破壁科技】：跨越 iframe 偷取 ST 的文字颜色！
        // ==========================================
        try {
            // 找到外层 ST 的聊天文本颜色
            const parentElem = window.parent.document.querySelector('.mes_text') || window.parent.document.body;
            const stColor = window.parent.getComputedStyle(parentElem).color;
            if (stColor) {
                // 强制把我们自己的身体染成外面的颜色
                document.body.style.color = stColor;
            }
        } catch(e) {
            // 如果读取失败，默认给一个适合深色模式的浅灰色
            document.body.style.color = "#e0e0e0";
        }

        // ==========================================
        // 以下是你绝对能用、绝对不能改的折叠和填入逻辑
        // ==========================================
        const panel = document.getElementById('destinyPanel');
        const header = document.getElementById('destinyHeader');
        header.addEventListener('click', () => panel.classList.toggle('collapsed'));

        function getInput() {
            try { return window.parent.document.querySelector('#send_textarea') || window.top.document.querySelector('#send_textarea'); } 
            catch(e) { return document.getElementById('send_textarea') || document.querySelector('textarea'); }
        }

        function appendToInput(text) {
            const input = getInput();
            if (!input) return;
            const current = input.value;
            input.value = current.trim() === '' ? text : current + ' ' + text;
            input.dispatchEvent(new Event('input', { bubbles: true }));
        }

        const options = document.querySelectorAll('.destiny-option');
        let currentSelected = null;
        options.forEach(opt => {
            opt.addEventListener('click', (e) => {
                e.stopPropagation();
                const text = opt.getAttribute('data-option');
                if (text) {
                    appendToInput(text);
                    if (currentSelected) currentSelected.classList.remove('selected');
                    opt.classList.add('selected');
                    currentSelected = opt;
